let config={firebase:null,mapsKey:null,sms:false,whatsapp:false,live:false},auth=null,fb=null,user=null,page='inicio',scope='demo',contacts=[],prefs={},position=null,watch=null,locationError='',installedEvent=null,activeAlert=null,countTimer=null,holdTimer=null,holdStart=0,tour=0,refreshTimer=null,previousFocus=null,confirmedPhone=null,editId=null,authBusy=false;
const types=[['geral','shield','Preciso de ajuda'],['violencia','heart','Violência'],['perseguicao','walk','Perseguição'],['saude','health','Problema de saúde'],['domestica','home','Emergência em casa']];
let locationRequest=0;
