const storage={get(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Não foi possível salvar neste dispositivo. Verifique o armazenamento.')}}};
function loadScope(){const saved=storage.get(storagePrefix+scope+':contacts',[]);contacts=Array.isArray(saved)?saved.filter(c=>c&&/^[\da-f-]{36}$/i.test(c.id)&&typeof c.name==='string'&&c.name.trim()&&c.name.length<=50&&normalizePhone(c.phone)===c.phone).slice(0,5).map(c=>({...c,relation:typeof c.relation==='string'?c.relation.slice(0,40):'',active:c.active===true,consent:c.consent===true})):[];const savedPrefs=storage.get(storagePrefix+scope+':prefs',{});prefs={demo:savedPrefs?.device!==true,device:savedPrefs?.device===true,large:savedPrefs?.large===true,contrast:savedPrefs?.contrast===true,theme:['light','dark','system'].includes(savedPrefs?.theme)?savedPrefs.theme:'light'};applyPrefs()}
function saveContacts(){storage.set(storagePrefix+scope+':contacts',contacts)}
function savePrefs(){storage.set(storagePrefix+scope+':prefs',prefs);applyPrefs()}
function applyPrefs(){document.body.classList.toggle('large-text',!!prefs.large);document.body.classList.toggle('contrast',!!prefs.contrast);const dark=prefs.theme==='dark'||(prefs.theme==='system'&&window.matchMedia?.('(prefers-color-scheme: dark)').matches===true);document.body.classList.toggle('dark',dark);$('meta[name="theme-color"]')?.setAttribute?.('content',dark?'#17111f':'#6527a1')}
function toast(s){$('#toastRoot').innerHTML='<div class="toast" role="status">'+esc(s)+'</div>';setTimeout(()=>{$('#toastRoot').innerHTML=''},6500)}
function announce(s){$('#urgent').textContent=s}
function nav(){for(const [id]of [['sidenav'],['bottomnav']])$('#'+id).innerHTML=pages.map(([key,i,label])=>'<button class="'+(id==='sidenav'?'navitem ':'')+(page===key?'active':'')+'" data-page="'+key+'" '+(page===key?'aria-current="page"':'')+'>'+icon(i)+'<span>'+label+'</span></button>').join('');$('#crumb').textContent=pages.find(x=>x[0]===page)?.[2]||'Pedido de ajuda';$('#modeBadge').innerHTML='<span class="dot"></span>'+(prefs.demo?'Demonstração':prefs.device?'Envio pelo celular':'Envio real');$('#modeBadge').className='pill '+(prefs.demo?'':'red');$('#accountButton').innerHTML=icon('user')+' '+(user?esc((user.displayName||'Minha conta').split(' ')[0]):'Entrar');$('#accountButton').dataset.action=user?'account':'login'}
function contactRows(){return contacts.filter(c=>c.active).slice(0,3).map(c=>'<div class="contact-row"><span class="avatar">'+esc(c.name.slice(0,2).toUpperCase())+'</span><div class="contact-info"><b>'+esc(c.name)+'</b><p>'+esc(c.relation||'Contato de confiança')+'</p></div><span class="pill green" style="font-size:9px">Selecionado</span></div>').join('')}
function home(){const name=user?.displayName?.split(' ')[0];return '<div class="greeting"><div><h2>Olá'+(name?', '+esc(name):'')+'. Este espaço é seu.</h2><p>Sua segurança começa com uma rede de confiança.</p></div><span class="date">'+esc(new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long'}).format(new Date()))+'</span></div><div class="grid"><section class="card sos-card"><div class="eyebrow">JUNTAS, MAIS SEGURAS</div><h1>Um gesto. Uma rede<br>inteira <span>com você.</span></h1><p>Avise suas pessoas de confiança quando<br>precisar de ajuda.</p><div class="sos-wrap"><button class="sos" id="sos" aria-label="Segure por três segundos para iniciar pedido de ajuda">'+icon('bell')+'<b>SOS</b><span id="holdText">Segure por 3 segundos</span></button></div><div class="holdhint">'+icon('lock')+' Você pode cancelar antes do envio.</div><button class="textlink" data-action="confirmAlert">Prefiro tocar para confirmar</button><div class="sos-bottom"><span>'+icon('shield')+(prefs.demo?'Teste sem enviar mensagens':'Somente seus contatos')+'</span><span>'+icon('pin')+'Localização com permissão</span></div></section><div class="rightstack"><section class="card"><div class="section-head"><h2>Sua rede de confiança</h2><button data-page="contatos">Gerenciar '+icon('arrow')+'</button></div>'+(contacts.filter(c=>c.active).length?contactRows():'<div class="empty">'+icon('users')+'<p>Quem você gostaria de ter por perto?</p><p class="small">Adicione alguém em quem confia.</p><button class="btn soft" data-action="addContact">'+icon('plus')+'Adicionar contato</button></div>')+'</section><section class="card map-card"><div class="map-art"><span class="map-label">'+(position?'Localização obtida':'Ilustração • localização não solicitada')+'</span><div class="map-pin">'+icon('pin')+'</div></div><div class="map-card-content"><div><h3>Sua localização, na hora certa</h3><p>'+(position?'Posição disponível neste dispositivo.':'Você escolhe quando permitir o acesso.')+'</p></div><button class="iconbutton" data-page="localizacao" aria-label="Abrir localização">'+icon('arrow')+'</button></div></section></div></div>'+voicePanel()+offlinePanel()+'<section class="situations"><h2>Que tipo de ajuda você precisa? <span>Opcional. O SOS funciona com um pedido geral.</span></h2><div class="type-grid">'+types.slice(1).map(([id,i,label])=>'<button class="type '+(selected===id?'active':'')+'" data-type="'+id+'" aria-pressed="'+(selected===id)+'"><span class="typeicon">'+icon(i)+'</span>'+label+'</button>').join('')+'</div></section><section class="banner"><div class="featureicon">'+icon('book')+'</div><div><h3>Primeira vez por aqui? Vamos juntas.</h3><p>Aprenda o essencial em poucos passos, no seu ritmo.</p></div><button class="btn soft" data-page="ajuda">Ver tutorial '+icon('arrow')+'</button></section>'}
function contactsPage(){return '<div class="page-title"><div><h1>Sua rede de confiança</h1><p>Pessoas que você escolhe para receber seus pedidos.</p></div><button class="btn primary" data-action="addContact">'+icon('plus')+'Adicionar</button></div><div class="notice" style="margin-bottom:20px">Combine antes com cada pessoa como ela pode ajudar. Os contatos ficam salvos somente neste navegador e nesta conta; não sincronizam entre aparelhos. Máximo de 5 contatos. Ao mudar de endereço, exporte os contatos aqui e importe no novo aplicativo. O arquivo contém dados pessoais: guarde-o com cuidado. O ícone de mensagem abre opções de envio manual por SMS ou WhatsApp.</div><div class="flow feature-actions" style="margin-bottom:20px"><button class="btn outline" data-action="exportContacts">Exportar contatos</button><button class="btn soft" data-action="chooseContactsFile">Importar contatos</button><input id="contactsFile" type="file" accept="application/json,.json" hidden></div><div class="stack">'+(contacts.length?contacts.map(c=>'<article class="contact-card"><span class="avatar">'+esc(c.name.slice(0,2).toUpperCase())+'</span><div class="contact-info"><b>'+esc(c.name)+'</b><p>'+esc(c.relation)+' · '+esc(c.phone)+'</p><p>'+(c.consent?'Aceite do contato informado':'Aceite do contato ainda não informado')+'</p></div><label class="check" style="margin:0;align-items:center"><input class="toggle" type="checkbox" data-contact-toggle="'+c.id+'" '+(c.active?'checked':'')+' aria-label="Incluir '+esc(c.name)+' nos alertas">Ativo</label><div class="flow" style="flex:none"><button class="iconbutton" data-manual="'+c.id+'" aria-label="Opções de envio manual para '+esc(c.name)+'">'+icon('message')+'</button><button class="iconbutton" data-edit="'+c.id+'" aria-label="Editar '+esc(c.name)+'">'+icon('edit')+'</button><button class="iconbutton" data-delete="'+c.id+'" aria-label="Excluir '+esc(c.name)+'">'+icon('trash')+'</button></div></article>').join(''):'<div class="card empty">'+icon('users')+'<h2>Sua rede começa com uma pessoa.</h2><p>Cadastre um telefone com DDD para começar.</p><button class="btn primary" data-action="addContact">Adicionar meu primeiro contato</button></div>')+'</div>'}
function locationPage(){return '<div class="page-title"><div><h1>Você no mapa</h1><p>Compartilhe uma posição atual com quem você confia.</p></div></div><section class="card"><div class="section-head"><h2>'+icon('pin')+' Localização do dispositivo</h2><span class="pill '+(position?'green':'')+'">'+(watch!==null?'Atualizando neste aparelho':position?'Posição obtida':'Não compartilhada')+'</span></div><div class="notice">O mapa não acompanha você com a tela bloqueada. As mensagens enviam uma posição do momento; não um link de rastreamento contínuo.</div><div class="maplarge" id="mapContainer">'+(position?'<div><div>'+icon('pin')+'</div><h3>Posição disponível</h3><p>'+esc(position.lat.toFixed(5))+', '+esc(position.lng.toFixed(5))+'</p><p>Precisão aproximada: '+Math.round(position.accuracy)+' metros.</p></div>':'<div>'+icon('pin')+'<h3>Só com sua permissão.</h3><p>Toque abaixo para localizar seu aparelho.<br>Nenhuma posição foi obtida ainda.</p></div>')+'</div><p id="locationState" class="small muted" style="margin-bottom:17px">'+esc(locationError||(position?'Atualizada às '+new Date(position.time).toLocaleTimeString('pt-BR'):'A localização pode falhar em ambientes fechados ou sem sinal.'))+'</p><div class="flow"><button class="btn primary" data-action="locate">'+icon('pin')+(position?'Atualizar posição':'Permitir localização')+'</button>'+(position?'<a class="btn outline" href="'+mapsUrl()+'" target="_blank" rel="noopener noreferrer">Abrir no Google Maps '+icon('arrow')+'</a>':'')+'</div><div class="flow" style="margin-top:12px"><button class="btn soft" data-action="'+(watch!==null?'stopLocation':'watchLocation')+'">'+icon('clock')+(watch!==null?'Parar e apagar posição':'Atualizar por 15 min neste aparelho')+'</button></div><p class="small muted" style="margin-top:16px">'+(config.mapsKey?'Google Maps configurado.':'Mapa integrado aguarda a chave Google Maps. O link para abrir a posição no Google Maps funciona sem chave.')+'</p></section>'}
const lessons=[['user','01 · Seu primeiro acesso','Entre uma vez. Acesse com facilidade.','Use sua conta Google ou seu número de celular. No acesso por celular, digite o código recebido por SMS. Nesta apresentação, você também pode explorar o modo de demonstração.'],['users','02 · Pessoas de confiança','Comece com quem cuida de você.','Abra Contatos e toque em Adicionar. Informe nome e telefone com DDD. Converse com a pessoa, confirme que ela aceita receber os alertas e marque essa confirmação.'],['pin','03 · Sua localização','Você decide quando permitir.','Abra Localização e toque em Permitir localização. Autorize o acesso no celular. Se não conseguir localizar, o pedido pode seguir informando que a localização está indisponível.'],['bell','04 · Na hora de pedir ajuda','Segure o SOS por três segundos.','Se quiser, escolha antes o tipo de situação. Segure o botão SOS por três segundos ou use Prefiro tocar para confirmar. A contagem de cinco segundos permite cancelar um acionamento acidental. Para usar voz, ative a escuta e diga: Conecta, preciso de ajuda. O aplicativo precisa ficar aberto e em primeiro plano.'],['message','05 · Acompanhe o pedido','Confira o resultado de cada canal.','No modo de demonstração, ninguém recebe mensagens. No envio real, confira o resultado por contato. Na fila não significa entregue. Você também pode abrir SMS ou WhatsApp e tocar em Enviar no próprio aplicativo.'],['download','06 · Sempre à mão','Adicione à tela inicial.','No iPhone: abra no Safari, toque em Compartilhar e em Adicionar à Tela de Início. No Android: abra no Chrome, toque no menu e em Instalar aplicativo ou Adicionar à tela inicial. O app precisa de internet para envios automáticos.']];
function helpPage(){const [i,k,title,body]=lessons[tour];return '<div class="page-title"><div><h1>Vamos juntas, passo a passo.</h1><p>Um guia simples para conhecer seu espaço de apoio.</p></div></div><section class="card tutorial"><div class="tutorial-art">'+icon(i)+'</div><div class="tutorial-content"><span class="eyebrow">'+k+'</span><h2>'+title+'</h2><p>'+body+'</p><div class="steps" aria-label="Passo '+(tour+1)+' de 6">'+lessons.map((_,n)=>'<span class="'+(n<=tour?'active':'')+'"></span>').join('')+'</div><div class="flow" style="margin-top:25px"><button class="btn outline" data-action="tourPrev" '+(tour===0?'disabled':'')+'>Anterior</button><button class="btn primary" data-action="tourNext">'+(tour===5?'Recomeçar':'Próximo passo')+icon('arrow')+'</button></div><button class="textlink" data-action="readLesson">'+icon('volume')+' Ouvir este passo</button><button class="textlink" data-action="stopVoice">Parar áudio</button></div></section><div class="helpgrid"><section class="helpcard"><div class="number">190</div><h3>Polícia Militar</h3><p>Para situações de emergência com risco imediato. A ligação é feita por você.</p><a class="btn outline" href="tel:190">'+icon('phone')+'Ligar 190</a></section><section class="helpcard"><div class="number">180</div><h3>Central de Atendimento à Mulher</h3><p>Orientação e denúncias. Em emergência, acione o 190.</p><a class="btn outline" href="tel:180">'+icon('phone')+'Ligar 180</a></section></div><details><summary>O que acontece sem internet?</summary><p>Após a preparação indicada na tela, a interface, os contatos, os temas, o tutorial e o SOS manual funcionam sem internet. Nenhum pedido fica na fila para envio posterior. O envio automático, o login e os mapas precisam de internet. Abrir um SMS manual pode funcionar com sinal de telefonia; você precisa confirmar o envio e a operadora pode cobrar.</p></details><details><summary>O SOS funciona com a tela bloqueada?</summary><p>Esta versão é um aplicativo web instalável. Não modifica a tela de bloqueio e não garante localização nem gestos em segundo plano. Deixe o aplicativo aberto para usar o SOS.</p></details><details><summary>Modo leitura apaga o histórico?</summary><p>Não. Ele mostra uma página neutra dentro do aplicativo. Não apaga histórico, mensagens, notificações nem esconde o app do sistema. Use somente se fizer sentido para a sua situação.</p></details><p class="small muted" style="margin-top:20px">Informações de atendimento: <a href="https://www.gov.br/mulheres/pt-br/ligue180" target="_blank" rel="noopener noreferrer">Ministério das Mulheres</a>. O Conecta Segura não aciona serviços públicos automaticamente.</p>'}
function settingsPage(){return '<div class="page-title"><div><h1>Do seu jeito</h1><p>Ajustes simples para usar com mais conforto.</p></div></div><section class="card"><h2>Acessibilidade e privacidade</h2><div class="setting"><div><h3>Aparência</h3><p>Escolha como prefere ver o aplicativo.</p></div><label class="theme-choice"><span class="sr-only">Tema do aplicativo</span><select id="appTheme" data-theme aria-label="Tema do aplicativo">'+[['light','Claro'],['dark','Escuro'],['system','Automático']].map(([value,label])=>'<option value="'+value+'" '+(prefs.theme===value?'selected':'')+'>'+label+'</option>').join('')+'</select></label></div><div class="setting"><div><h3>Texto maior</h3><p>Aumenta o tamanho da leitura.</p></div><input type="checkbox" class="toggle" data-pref="large" '+(prefs.large?'checked':'')+' aria-label="Texto maior"></div><div class="setting"><div><h3>Mais contraste</h3><p>Deixa textos e bordas mais definidos.</p></div><input type="checkbox" class="toggle" data-pref="contrast" '+(prefs.contrast?'checked':'')+' aria-label="Mais contraste"></div><div class="setting"><div><h3>Modo de demonstração</h3><p>Pratique o SOS sem enviar mensagens.</p></div><input type="checkbox" class="toggle" id="demoToggle" '+(prefs.demo?'checked':'')+' aria-label="Modo de demonstração"></div><div class="setting"><div><h3>Modo leitura</h3><p>Abre um conteúdo neutro. Não apaga histórico.</p></div><button class="btn outline" data-action="reading">Abrir</button></div><div class="setting"><div><h3>Instalar no celular</h3><p>Tenha um atalho na tela inicial.</p></div><button class="btn soft" data-action="install">'+icon('download')+'Instalar</button></div><div class="setting" style="border:0"><div><h3>Dados neste aparelho</h3><p>Apaga contatos, preferências e a posição desta conta neste navegador.</p></div><button class="iconbutton" data-action="clearData" aria-label="Apagar dados locais">'+icon('trash')+'</button></div></section><section class="card" style="margin-top:20px"><div class="section-head"><h2>Conexões do aplicativo</h2><span class="pill">'+(config.live?'Envio configurado':config.backend?'Servidor disponível':runtime.static&&!runtime.apiBase?'Demonstração local':'Configuração pendente')+'</span></div>'+[['Servidor do aplicativo',config.backend,'Rotas da aplicação respondendo neste endereço.'],['Registro de pedidos',config.storage,'Armazenamento persistente dos resultados de alertas.'],['Google Maps',config.mapsKey,'Mapa interativo e link com a posição.'],['Login Google / celular',config.firebase,'Autenticação com código SMS ou conta Google.'],['SMS automático',config.sms,'Envio pelo servidor para contatos cadastrados.'],['WhatsApp automático',config.whatsapp,'Envio com modelo aprovado pelo provedor.']].map(([title,ready,desc])=>'<div class="setting"><div><h3>'+title+'</h3><p>'+desc+'</p></div><span class="pill '+(ready?'green':'amber')+'">'+(ready?'Configurado':'Pendente')+'</span></div>').join('')+'<p class="small muted" style="margin-top:16px">'+(runtime.static&&!runtime.apiBase?'Esta versão pública não possui servidor de envio. Login e envios automáticos aguardam configuração. ':'')+'Configuração disponível não garante entrega. Os envios reais dependem de internet, saldo, aceite dos destinatários e testes dos provedores.</p><a class="textlink" style="display:inline-block;margin-top:12px" href="./implantacao/" target="_blank" rel="noopener noreferrer">Guia de ativação para a equipe técnica</a></section>'+voicePanel()+offlinePanel()}
function render(focus=false){stopHold();nav();$('#main').innerHTML=({inicio:home,contatos:contactsPage,localizacao:locationPage,ajuda:helpPage,ajustes:settingsPage,alerta:alertPage}[page]||home)()+ '<footer class="footer"><span>'+icon('shield')+'Conecta Segura · Tecnologia que acolhe.</span><span>Desenvolvido para aproximar, apoiar e proteger.</span></footer>';if(page==='inicio')bindHold();if(page==='localizacao'&&position)drawMap();if(focus)$('#main').focus({preventScroll:true})}
function navigate(p){if(countTimer&&p!=='alerta'){toast('Cancele a contagem antes de sair.');return}page=p;history.replaceState(null,'','#'+p);render(true);window.scrollTo({top:0,behavior:'instant'});window.speechSynthesis?.cancel()}
function modal(html){closeModal();previousFocus=document.activeElement;$('#modalRoot').innerHTML='<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialogTitle">'+html+'</section></div>';const first=$('#modalRoot input, #modalRoot button, #modalRoot a');first?.focus()}
function modalHead(title){return '<div class="modal-head"><h2 id="dialogTitle">'+title+'</h2><button class="iconbutton" data-action="closeModal" aria-label="Fechar">'+icon('close')+'</button></div>'}
function closeModal(){const open=!!$('#modalRoot').firstChild;$('#modalRoot').innerHTML='';if(open)previousFocus?.focus?.()}
function manualContact(c){const pos=freshLocation();const text=(user?.displayName||'Uma pessoa da sua rede')+' precisa de ajuda. Situação: '+types.find(t=>t[0]===selected)[2]+'. '+(pos?'Localização: '+mapsUrl(pos):'Localização indisponível.')+' Entre em contato para verificar a situação.';modal(modalHead('Preparar mensagem para '+esc(c.name))+'<p>Este é um envio manual real, mesmo com a demonstração ativa. Você precisa tocar em Enviar no aplicativo escolhido.</p><div class="notice">'+esc(text)+'</div>'+(!c.consent?'<p class="small muted" style="margin-top:12px">Combine antes com essa pessoa o recebimento dos seus alertas.</p>':'')+'<div class="flow" style="margin-top:20px"><a class="btn primary" href="'+esc(waHref(c.phone,text))+'" target="_blank" rel="noopener noreferrer">Abrir WhatsApp</a><a class="btn outline" href="'+esc(smsHref(c.phone,text))+'">Abrir SMS</a></div><p class="small muted" style="margin-top:15px">Abrir a conversa não confirma envio ou entrega. SMS pode ter custo na operadora.</p>')}

function contactBackup(){return {app:'Conecta Segura',version:1,contacts:contacts.map(({name,phone,relation,active,consent})=>({name,phone,relation,active,consent}))}}
function parseContactBackup(text){
 const data=JSON.parse(text);if(data?.app!=='Conecta Segura'||data.version!==1||!Array.isArray(data.contacts)||data.contacts.length>5)throw Error('Arquivo de contatos inválido.');
 const seen=new Set();return data.contacts.map(c=>{if(!c||typeof c.name!=='string'||!c.name.trim()||c.name.length>50||typeof c.phone!=='string'||normalizePhone(c.phone)!==c.phone||typeof c.relation!=='string'||c.relation.length>40||seen.has(c.phone))throw Error('Confira o formato e os telefones do arquivo.');seen.add(c.phone);return {id:crypto.randomUUID(),name:c.name.trim(),phone:c.phone,relation:c.relation,active:c.active===true,consent:c.consent===true}});
}
function exportContacts(){if(!contacts.length){toast('Não há contatos para exportar.');return}const blob=new Blob([JSON.stringify(contactBackup(),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='conecta-segura-contatos.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Arquivo preparado neste aparelho. Ele contém dados pessoais.');}
async function importContactsFile(input){const file=input.files?.[0];if(!file)return;const importScope=scope;try{if(file.size>16384)throw Error('O arquivo deve ter até 16 KB.');const imported=parseContactBackup(await file.text());if(scope!==importScope)throw Error('A conta mudou. Importe novamente na conta desejada.');const additions=imported.filter(c=>!contacts.some(old=>old.phone===c.phone));if(contacts.length+additions.length>5)throw Error('A importação ultrapassa o limite de cinco contatos.');contacts=[...contacts,...additions];saveContacts();render();toast(additions.length+' contato(s) importado(s) neste navegador. Confira o aceite com cada pessoa.');}catch(e){toast(e.message||'Não foi possível importar este arquivo.')}finally{input.value=''}}

function contactForm(c){editId=c?.id||null;if(!c&&contacts.length>=5){toast('Você já tem cinco contatos. Edite ou exclua um para adicionar outro.');return}modal(modalHead(c?'Editar contato':'Alguém em quem você confia')+'<p>Informe o número com código do país e DDD. Exemplo de formato: +55 92 9XXXX-XXXX.</p><form id="contactForm"><div class="form-field"><label for="contactName">Nome</label><input id="contactName" autocomplete="off" required maxlength="50" value="'+esc(c?.name||'')+'"></div><div class="form-field"><label for="contactRelation">Como vocês se conhecem?</label><input id="contactRelation" maxlength="40" placeholder="Ex.: irmã, amiga, vizinha" value="'+esc(c?.relation||'')+'"></div><div class="form-field"><label for="contactPhone">Celular com DDD</label><input id="contactPhone" type="tel" inputmode="tel" required placeholder="+55 92 9XXXX-XXXX" value="'+esc(c?.phone||'')+'"></div><label class="check"><input id="contactConsent" type="checkbox" '+(c?.consent?'checked':'')+'>Conversei com essa pessoa e ela aceitou receber meus pedidos de ajuda por SMS e WhatsApp.</label><p class="small muted" id="contactError" role="alert"></p><button class="btn primary full" type="submit" style="margin-top:15px">Salvar contato</button></form>')}
function normalizePhone(value){if(typeof value!=='string'||!/^\+?[\d\s().-]+$/.test(value.trim()))return null;let p=value.replace(/\D/g,'');if(!value.trim().startsWith('+')&&(p.length===10||p.length===11))p='55'+p;if(!/^[1-9]\d{9,14}$/.test(p)||/^(\d)\1+$/.test(p))return null;if(p.startsWith('55')){const ddd=Number(p.slice(2,4)),subscriber=p.slice(4);if(![11,12,13,14,15,16,17,18,19,21,22,24,27,28,31,32,33,34,35,37,38,41,42,43,44,45,46,47,48,49,51,53,54,55,61,62,63,64,65,66,67,68,69,71,73,74,75,77,79,81,82,83,84,85,86,87,88,89,91,92,93,94,95,96,97,98,99].includes(ddd)||!/^([2-5]\d{7}|9\d{8})$/.test(subscriber))return null;}return '+'+p;}
function login(){modal('<div class="logo">'+logo+'</div>'+modalHead('Seu primeiro passo por aqui')+'<p>Entre com Google ou receba um código no seu celular. Sua senha do Google nunca é solicitada aqui.</p>'+(!config.firebase?'<div class="notice warning" style="margin-bottom:16px">Login real ainda não ativado. É necessário configurar o Firebase Authentication.</div>':'')+'<button class="btn outline full" data-action="googleLogin">'+icon('user')+'Continuar com o Google</button><div class="divider">ou use seu celular</div><form id="phoneForm"><div class="form-field"><label for="loginPhone">Seu celular com DDD</label><input id="loginPhone" type="tel" autocomplete="tel" inputmode="tel" placeholder="+55 92 9XXXX-XXXX" required></div><div id="recaptcha"></div><p class="small muted">Um SMS de verificação será enviado para este número. A autenticação por telefone usa o serviço Google e verificação antiabuso.</p><button class="btn primary full" id="phoneSubmit" type="submit" style="margin-top:15px">Receber código por SMS</button></form><p id="authError" role="alert" class="small" style="color:#9e2444;margin-top:15px"></p><button class="textlink" data-action="demoLogin" style="display:block;margin:10px auto 0">Explorar a demonstração sem criar conta</button>')}
async function initFirebase(){if(!config.firebase)throw Error('Login pendente de configuração. Você pode explorar a demonstração.');if(!fb){const [app,mod]=await Promise.all([import('https://www.gstatic.com/firebasejs/12.4.0/firebase-app.js'),import('https://www.gstatic.com/firebasejs/12.4.0/firebase-auth.js')]);fb=mod;auth=mod.getAuth(app.initializeApp(config.firebase));auth.languageCode='pt-BR';await mod.setPersistence(auth,mod.browserSessionPersistence);mod.onAuthStateChanged(auth,u=>{if(countTimer)cancelCountdown();if(user?.uid!==u?.uid){activeAlert=null;stopLocation()}voice?.stop();user=u;scope=u?'user:'+u.uid:'demo';loadScope();render()})}return fb}
async function googleLogin(){if(authBusy)return;authBusy=true;try{const m=await initFirebase();await m.signInWithPopup(auth,new m.GoogleAuthProvider());closeModal();toast('Você entrou. Cadastre seus contatos de confiança.')}catch(e){authError(e)}finally{authBusy=false}}
function authError(e){const known={'auth/popup-blocked':'Permita a janela de login no navegador e tente novamente.','auth/popup-closed-by-user':'O login foi fechado. Tente novamente quando quiser.','auth/invalid-verification-code':'Código incorreto. Confira o SMS.','auth/too-many-requests':'Muitas tentativas. Aguarde antes de tentar novamente.','auth/invalid-phone-number':'Confira o celular com código do país e DDD.','auth/unauthorized-domain':'Este endereço precisa ser autorizado no Firebase.'};const message=known[e.code]||(config.firebase?'Não foi possível entrar. Confira sua conexão e a configuração do login.':e.message);if($('#authError'))$('#authError').textContent=message;else toast(message)}
async function phoneLogin(){if(authBusy)return;const phone=normalizePhone($('#loginPhone').value);if(!phone){$('#authError').textContent='Confira o celular com DDD.';return}authBusy=true;try{const m=await initFirebase();window.csRecaptcha?.clear();window.csRecaptcha=new m.RecaptchaVerifier(auth,'recaptcha',{size:'normal'});confirmedPhone=await m.signInWithPhoneNumber(auth,phone,window.csRecaptcha);modal(modalHead('Confira o SMS no seu celular')+'<p>Enviamos um código de verificação. Ele só confirma que este telefone é seu.</p><form id="codeForm"><div class="form-field"><label for="smsCode">Código recebido</label><input id="smsCode" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></div><button class="btn primary full" type="submit">Confirmar e entrar</button><p id="authError" role="alert" class="small" style="color:#9e2444;margin-top:14px"></p></form>')}catch(e){authError(e)}finally{authBusy=false}}
async function codeLogin(){if(authBusy)return;authBusy=true;try{await confirmedPhone.confirm($('#smsCode').value);closeModal();toast('Celular confirmado. Bem-vinda ao seu espaço.')}catch(e){authError(e)}finally{authBusy=false}}
function bindHold(){const b=$('#sos');let activated=false;const stop=()=>{if(holdTimer!==null)clearInterval(holdTimer);holdTimer=null;b.classList.remove('holding');if($('#holdText'))$('#holdText').textContent='Segure por 3 segundos'};stopHold=stop;const start=e=>{if(e.type==='keydown'&&![' ','Enter'].includes(e.key))return;if(e.type==='pointerdown'&&(e.button!==0||e.isPrimary===false))return;if(e.repeat||holdTimer!==null)return;e.preventDefault();activated=false;holdStart=Date.now();b.classList.add('holding');if(e.type==='pointerdown')b.setPointerCapture?.(e.pointerId);holdTimer=setInterval(()=>{const left=Math.max(0,3-(Date.now()-holdStart)/1000);if($('#holdText'))$('#holdText').textContent='Continue segurando… '+Math.ceil(left);if(!left){activated=true;stop();startCountdown()}},75)};b.addEventListener('pointerdown',start);b.addEventListener('pointerup',()=>{const held=Date.now()-holdStart;stop();if(!activated&&held<500)toast('Segure por 3 segundos ou use “Prefiro tocar para confirmar”.')});for(const event of ['pointercancel','lostpointercapture','blur'])b.addEventListener(event,stop);b.addEventListener('keydown',start);b.addEventListener('keyup',e=>{if([' ','Enter'].includes(e.key))stop()});b.addEventListener('click',e=>{if(e.detail===0&&!activated&&holdTimer===null)confirmAlert()});b.addEventListener('contextmenu',e=>e.preventDefault())}
function confirmAlert(){modal(modalHead(prefs.demo?'Testar pedido de ajuda?':'Iniciar pedido de ajuda?')+'<p>'+(prefs.demo?'Este teste não envia mensagens.':(prefs.device||!(config.live&&user)?'Depois de 5 segundos, o app abre o SMS e o WhatsApp dos contatos ativos com a mensagem pronta. Você confirma o envio.':'Será iniciada uma contagem de 5 segundos para envio aos contatos ativos.'))+'</p><div class="form-field"><label for="emergencyType">Tipo de situação</label><select id="emergencyType">'+types.map(([id,,name])=>'<option value="'+id+'" '+(id===selected?'selected':'')+'>'+name+'</option>').join('')+'</select></div><div class="flow"><button class="btn outline" data-action="closeModal">Voltar</button><button class="btn danger" data-action="startAlert">'+(prefs.demo?'Iniciar teste':'Iniciar contagem')+'</button></div>')}
function startCountdown({manual=false}={}){voice?.stop();if(activeAlert&&!activeAlert.finished){toast('Já existe um pedido em andamento.');navigate('alerta');return}manual=manual||(!prefs.demo&&(prefs.device||!navigator.onLine||!(config.live&&user)));if(!prefs.demo&&!manual){if(!config.live||!user){toast('O envio real precisa de login e configuração dos provedores.');navigate('ajustes');return}if(!contacts.some(c=>c.active&&c.consent)){toast('Cadastre e ative pelo menos um contato que aceitou receber alertas.');navigate('contatos');return}if(!navigator.onLine){toast('Sem internet. Use ligação ou envio manual.');return}}
activeAlert={id:crypto.randomUUID(),demo:manual?false:prefs.demo,manual,stage:'countdown',remaining:5,opened:{},type:selected,contacts:contacts.filter(c=>c.active&&(manual||prefs.demo||c.consent)).map(c=>({...c})),created:Date.now(),location:null,results:[]};navigate('alerta');$('#main [data-action="cancelAlert"]')?.focus();announce('Contagem iniciada. Você tem cinco segundos para cancelar.');if(!prefs.demo)quickLocate();countTimer=setInterval(()=>{if(!activeAlert)return;activeAlert.remaining--;if(activeAlert.remaining<=0){clearInterval(countTimer);countTimer=null;sendAlert()}else{const count=$('#countNumber');if(count)count.textContent=activeAlert.remaining;announce('Envio em '+activeAlert.remaining)}},1000)}
function cancelCountdown(){if(activeAlert?.stage!=='countdown')return;clearInterval(countTimer);countTimer=null;activeAlert.finished=true;activeAlert.stage='cancelled';announce('Pedido cancelado. Nenhuma mensagem foi enviada.');render()}
const isApple=()=>/iPhone|iPad|iPod/.test(navigator.userAgent||'')||((navigator.maxTouchPoints||0)>1&&/Mac/.test(navigator.platform||navigator.userAgent||''));
function smsHref(phone,text){return 'sms:'+phone+(isApple()?'&':'?')+'body='+encodeURIComponent(text)}
function waHref(phone,text){return 'https://wa.me/'+String(phone).replace(/\D/g,'')+'?text='+encodeURIComponent(text)}
function quickLocate(){if(!navigator.geolocation)return;const request=++locationRequest;navigator.geolocation.getCurrentPosition(p=>{if(request!==locationRequest)return;position={lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy,time:p.timestamp};if(activeAlert?.stage==='manual'&&!activeAlert.location){activeAlert.location=freshLocation();if(page==='alerta')render()}},()=>{},{enableHighAccuracy:true,timeout:8000,maximumAge:10000})}
function freshLocation(){return position&&Date.now()-position.time<60000?{...position}:null}
function mapsUrl(pos=position){return pos?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(pos.lat+','+pos.lng):''}
function message(){const a=activeAlert;return (user?.displayName||'Uma pessoa da sua rede')+' precisa de ajuda. Situação: '+types.find(t=>t[0]===a.type)[2]+'. '+(a.location?'Localização registrada às '+new Date(a.location.time).toLocaleTimeString('pt-BR')+': '+mapsUrl(a.location):'Localização indisponível.')+' Entre em contato para verificar a situação.'}
async function token(){return user?await user.getIdToken():null}
async function api(path,options={}){if(runtime.static&&!runtime.apiBase)throw Error('Backend não configurado. Use demonstração ou os atalhos manuais.');const idToken=await token();const r=await fetch((runtime.apiBase||'')+path,{...options,headers:{'Content-Type':'application/json',...(idToken?{Authorization:'Bearer '+idToken}:{}),...options.headers},signal:AbortSignal.timeout(45000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Não foi possível concluir.');return data}
async function sendAlert(){const a=activeAlert;if(!a||a.stage!=='countdown')return;const requestScope=scope;a.stage='sending';a.location=freshLocation();render();if(a.demo){a.stage='demo';a.results=a.contacts.map(c=>({name:c.name,channel:'Teste',status:'simulated'}));render();announce('Teste concluído. Nenhuma mensagem foi enviada.');return}if(a.manual||!navigator.onLine){a.manual=true;a.stage='manual';render();announce('SOS manual preparado. Nenhuma mensagem enviada. Confirme o envio no SMS.');return}try{const data=await api('/api/alerts',{method:'POST',body:JSON.stringify({id:a.id,type:a.type,contacts:a.contacts.map(({name,phone,consent})=>({name,phone,consent})),location:a.location,name:user.displayName||'Contato da sua rede'})});if(activeAlert!==a||scope!==requestScope)return;a.stage='result';a.results=data.results;render();announce('Solicitação processada. Consulte os resultados por contato.')}catch(e){if(activeAlert!==a||scope!==requestScope)return;a.stage='error';a.error=e.message+' O envio pode não ter sido concluído. Consulte o status antes de tentar novamente.';render();announce('Não foi possível confirmar o envio. Use as alternativas disponíveis.')}}
const labels={simulated:'Simulado • não enviado',queued:'Na fila do provedor',accepted:'Aceito pelo provedor',sending:'Em processamento',sent:'Enviado • entrega não confirmada',delivered:'Entregue',read:'Lido',failed:'Falhou',undelivered:'Não entregue',unknown:'Resultado não confirmado',processing:'Em processamento',not_configured:'Canal não configurado'};
function alertPage(){const a=activeAlert;if(a?.stage==='manual')return manualAlertPage(a);if(!a)return '<section class="card empty"><h1>Nenhum pedido em andamento.</h1><button class="btn primary" data-page="inicio">Voltar ao início</button></section>';if(a.stage==='countdown')return '<section class="card alert-panel">'+icon('bell')+'<div class="eyebrow">'+(a.demo?'TESTE SEM ENVIO':a.manual?'SOS MANUAL':'PEDIDO DE AJUDA')+'</div><h1>Um momento para confirmar.</h1><p class="muted" style="margin-top:13px">'+esc(types.find(t=>t[0]===a.type)[2])+' · '+a.contacts.length+' contato(s)</p><div class="count" id="countNumber" aria-hidden="true">'+a.remaining+'</div><p style="margin-bottom:20px">'+(a.demo?'A demonstração começa em instantes.':a.manual?'Os rascunhos serão preparados. Você confirma o envio.':'As mensagens serão solicitadas ao fim da contagem.')+'</p><button class="btn danger full" data-action="cancelAlert">Cancelar pedido</button></section>';if(a.stage==='cancelled')return '<section class="card alert-panel">'+icon('check')+'<h1>Pedido cancelado.</h1><p style="margin:20px 0">Nenhuma mensagem foi enviada.</p><button class="btn primary" data-page="inicio">Voltar ao início</button></section>';return '<div class="page-title"><div><h1>'+(a.stage==='sending'?'Solicitando envio…':a.demo?'Você concluiu o teste.':'Acompanhe seu pedido.')+'</h1><p>'+(a.demo?'Nenhuma pessoa foi avisada. Este é um ensaio do fluxo.':'Cada canal tem seu próprio resultado. Confira abaixo.')+'</p></div></div><section class="card"><div class="notice '+(a.stage==='error'?'error':'')+'">'+esc(a.stage==='error'?a.error:a.demo?'Demonstração: o aplicativo não enviou SMS nem WhatsApp.':'Uma solicitação ao provedor não garante entrega ou atendimento. Este aplicativo não chama a polícia automaticamente.')+'</div>'+(a.results.length?a.results.map(r=>'<div class="delivery"><div><b>'+esc(r.name)+'</b><p class="small muted">'+esc(r.channel)+'</p></div><span class="pill '+(['delivered','read'].includes(r.status)?'green':['failed','undelivered','unknown'].includes(r.status)?'amber':'')+'">'+esc(labels[r.status]||'Aguardando confirmação')+'</span></div>').join(''):'<p class="muted" style="margin-top:20px">'+(a.stage==='sending'?'Aguarde o retorno do servidor.':a.demo?'Adicione contatos para visualizar o teste por pessoa.':'Sem confirmação de resultado.')+'</p>')+(!a.demo&&a.stage!=='sending'?'<button class="btn outline full" style="margin-top:17px" data-action="refreshAlert">Atualizar status dos envios</button>':'')+'<p class="small muted" style="margin-top:19px">'+(a.location?'A mensagem usa a posição registrada às '+new Date(a.location.time).toLocaleTimeString('pt-BR')+'.':'Nenhuma posição recente foi incluída.')+'</p></section><section class="card" style="margin-top:18px"><h2>Outras formas de pedir ajuda</h2><p class="small muted" style="margin:9px 0 17px">Você confirma o envio no SMS ou WhatsApp. Abrir o aplicativo não significa que a mensagem foi enviada.</p>'+(a.demo?'<div class="notice">Os atalhos de mensagem real ficam desativados neste teste.</div>':a.contacts.map(c=>'<div class="delivery"><b>'+esc(c.name)+'</b><div class="flow"><a class="btn soft" href="'+esc(waHref(c.phone,message()))+'" target="_blank" rel="noopener noreferrer">WhatsApp</a><a class="btn outline" href="'+esc(smsHref(c.phone,message()))+'">SMS</a></div></div>').join(''))+'<div class="flow" style="margin-top:18px"><a class="btn outline" href="tel:190">'+icon('phone')+'Ligar 190</a><a class="btn outline" href="tel:180">'+icon('phone')+'Ligar 180</a><button class="btn soft" data-action="finishAlert">Encerrar visualização</button></div><p class="small muted" style="margin-top:12px">Encerrar esta tela não recolhe mensagens já enviadas. Sem reenvio automático.</p></section>'}
async function refreshAlert(){if(!activeAlert||activeAlert.demo||activeAlert.manual)return;try{const r=await api('/api/alerts/'+activeAlert.id);activeAlert.results=r.results;activeAlert.stage='result';render();toast('Status consultado no provedor.')}catch(e){toast(e.message)}}
function locate(live=false){if(!navigator.geolocation){toast('Localização não disponível neste navegador.');return}const request=++locationRequest;if(watch!==null){navigator.geolocation.clearWatch(watch);watch=null;clearTimeout(refreshTimer)}locationError='';const ok=p=>{if(request!==locationRequest)return;position={lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy,time:p.timestamp};locationError='';if(page==='localizacao')render();else toast('Posição obtida. Ela só será incluída se estiver recente ao enviar.')};const fail=e=>{if(request!==locationRequest)return;if(watch!==null)navigator.geolocation.clearWatch(watch);watch=null;position=null;clearTimeout(refreshTimer);locationError=e.code===1?'Permissão negada. Autorize a localização nas configurações do navegador.':e.code===3?'A localização demorou demais. Tente novamente.':'Não foi possível obter a posição. Verifique o sinal do aparelho.';if(page==='localizacao')render();toast(locationError)};if(live){if(watch!==null)navigator.geolocation.clearWatch(watch);watch=navigator.geolocation.watchPosition(ok,fail,{enableHighAccuracy:true,timeout:12000,maximumAge:15000});clearTimeout(refreshTimer);refreshTimer=setTimeout(stopLocation,15*60*1000);toast('Atualização neste aparelho por até 15 minutos. Mantenha o app aberto.')}else navigator.geolocation.getCurrentPosition(ok,fail,{enableHighAccuracy:true,timeout:12000,maximumAge:0})}
function stopLocation(){locationRequest++;if(watch!==null)navigator.geolocation.clearWatch(watch);watch=null;position=null;clearTimeout(refreshTimer);if(page==='localizacao')render();toast('Atualização parada. A posição foi apagada deste aparelho.')}
let mapsPromise=null;
async function drawMap(){if(!config.mapsKey||!position)return;const pos={...position};try{if(!window.google?.maps){if(!mapsPromise)mapsPromise=new Promise((resolve,reject)=>{window.csMapReady=resolve;window.gm_authFailure=()=>{mapsPromise=null;reject(Error('Mapa indisponível'))};const script=document.createElement('script');script.src='https://maps.googleapis.com/maps/api/js?key='+encodeURIComponent(config.mapsKey)+'&loading=async&callback=csMapReady';script.async=true;script.onerror=()=>{mapsPromise=null;reject(Error('Mapa indisponível'))};document.head.appendChild(script)});await mapsPromise}if(page!=='localizacao'||!$('#mapContainer')||!position)return;$('#mapContainer').innerHTML='<div id="googleMap" aria-label="Mapa da sua posição"></div>';const center={lat:pos.lat,lng:pos.lng};const map=new google.maps.Map($('#googleMap'),{center,zoom:16,disableDefaultUI:true,zoomControl:true});new google.maps.Circle({map,center,radius:Math.max(pos.accuracy,10),fillColor:'#6527a1',fillOpacity:.18,strokeColor:'#6527a1',strokeWeight:1});new google.maps.Circle({map,center,radius:5,fillColor:'#6527a1',fillOpacity:1,strokeColor:'#ffffff',strokeWeight:2})}catch{toast('Mapa indisponível. O link Google Maps continua disponível.')}}
async function install(){if(installedEvent){await installedEvent.prompt();await installedEvent.userChoice;installedEvent=null;return}modal(modalHead('Leve seu espaço com você')+'<p>Instale pelo menu do navegador. O nome exibido é Conecta Segura.</p><div class="notice"><b>iPhone / iPad</b><br>1. Abra este endereço no Safari.<br>2. Toque em Compartilhar.<br>3. Escolha Adicionar à Tela de Início.<br><br><b>Android</b><br>1. Abra no Chrome.<br>2. Toque no menu de três pontos.<br>3. Escolha Instalar aplicativo ou Adicionar à tela inicial.</div><p class="small muted" style="margin-top:18px">A disponibilidade depende do navegador e do aparelho. Instalar não permite usar o SOS com a tela bloqueada.</p><button class="btn primary full" data-action="closeModal">Entendi</button>')}
function reading(){voice?.stop();stopHold();closeModal();if($('#reading'))return;if(countTimer)cancelCountdown();window.speechSynthesis?.cancel();const el=document.createElement('section');el.className='reading';el.id='reading';el.innerHTML='<article><span class="eyebrow" style="color:#786a54">LEITURA DO DIA</span><h1>Pequenas pausas,<br>novos caminhos.</h1><p>Às vezes, tudo o que precisamos é de um momento para respirar. Observar a luz entrando pela janela, perceber os sons ao redor e deixar o tempo seguir sem pressa.</p><p style="margin-top:25px">Cada dia abre espaço para uma nova página. E cada pequena escolha pode nos aproximar do que faz bem.</p><button class="btn outline" data-action="leaveReading">Voltar à página inicial</button><small>Leitura · Uma pausa no seu dia</small></article>';document.body.appendChild(el);el.querySelector('button').focus()}
function setDemo(checked){voice?.stop();if(checked){prefs.demo=true;prefs.device=false;savePrefs();render();return}if(!config.live||!user){modal(modalHead('Ativar envio pelo celular?')+'<p>O SOS vai preparar o SMS e o WhatsApp dos seus contatos ativos, com a mensagem e a localização (se você permitir). Você toca em Enviar em cada conversa.</p><div class="notice warning">Nenhuma mensagem sai sozinha. O SMS usa o sinal da operadora e pode ser cobrado; o WhatsApp precisa de internet. Isto não substitui ligar para o 190 ou o 180.</div><div class="flow" style="margin-top:20px"><button class="btn outline" data-action="closeReal">Manter demonstração</button><button class="btn danger" data-action="enableDevice">Ativar envio pelo celular</button></div>');return}modal(modalHead('Ativar envio real?')+'<p>O SOS poderá solicitar mensagens aos seus contatos ativos que aceitaram recebê-las. Esses envios podem gerar custos no provedor.</p><div class="notice warning">Teste as integrações com números autorizados antes de usar. Entrega e atendimento não são garantidos.</div><div class="flow" style="margin-top:20px"><button class="btn outline" data-action="closeReal">Manter demonstração</button><button class="btn danger" data-action="enableReal">Ativar envio real</button></div>')}
const actions={exportContacts,chooseContactsFile:()=>$('#contactsFile')?.click(),voiceDialog,startVoiceLocal:()=>startVoice('local'),startVoiceBrowser:()=>startVoice('browser'),stopListening:()=>voice?.stop(),downloadVoice:()=>voice?.download(),confirmManualAlert,startManualAlert:()=>{closeModal();startCountdown({manual:true})},login,googleLogin,closeModal,addContact:()=>contactForm(),reading,leaveReading:()=>{$('#reading')?.remove();navigate('inicio')},install,locate:()=>locate(),watchLocation:()=>locate(true),stopLocation,confirmAlert,startAlert:()=>{selected=$('#emergencyType')?.value||selected;closeModal();startCountdown()},cancelAlert:cancelCountdown,refreshAlert,finishAlert:()=>{if(activeAlert?.stage==='sending'){toast('Aguarde o retorno do pedido em andamento.');return}if(activeAlert)activeAlert.finished=true;navigate('inicio')},demoLogin:()=>{prefs.demo=true;savePrefs();closeModal();navigate('inicio');toast('Demonstração ativa. Nenhuma mensagem será enviada.')},tourPrev:()=>{tour=Math.max(0,tour-1);render();announce('Passo '+(tour+1))},tourNext:()=>{tour=(tour+1)%6;render();announce('Passo '+(tour+1))},readLesson:()=>{voice?.stop();if(!('speechSynthesis'in window)){toast('A leitura em voz alta não está disponível neste navegador. O texto completo está na tela.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(lessons[tour][2]+'. '+lessons[tour][3]);u.lang='pt-BR';u.rate=.9;speechSynthesis.speak(u)},stopVoice:()=>window.speechSynthesis?.cancel(),enableReal:()=>{voice?.stop();prefs.demo=false;prefs.device=false;savePrefs();closeModal();render()},enableDevice:()=>{voice?.stop();prefs.demo=false;prefs.device=true;savePrefs();closeModal();render();toast('Envio pelo celular ativado. Cadastre seus contatos e teste com alguém de confiança.')},markOpened:btn=>{const key=btn?.dataset?.mark;if(!key||!activeAlert)return;activeAlert.opened[key]=true;const el=$('[data-opened="'+key.split(':')[0]+'"]');if(el)el.textContent='Rascunho aberto'},shareMessage:async()=>{try{await navigator.share({title:'Conecta Segura',text:message()})}catch{}},copyMessage:async()=>{try{await navigator.clipboard.writeText(message());toast('Mensagem copiada.')}catch{toast('Não foi possível copiar. Selecione o texto na tela.')}},refreshManualLocation:()=>{if(!navigator.geolocation){toast('Localização não disponível neste navegador.');return}navigator.geolocation.getCurrentPosition(p=>{position={lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy,time:p.timestamp};if(activeAlert&&activeAlert.stage==='manual'){activeAlert.location=freshLocation();if(page==='alerta')render()}},()=>toast('Não foi possível obter a posição. Verifique a permissão e o sinal do aparelho.'),{enableHighAccuracy:true,timeout:10000,maximumAge:0})},closeReal:()=>{closeModal();render()},account:()=>modal(modalHead('Sua conta')+'<p>'+esc(user?.displayName||user?.phoneNumber||user?.email||'Conta conectada')+'</p><p class="small muted">Seus contatos ficam apenas neste navegador. Ao sair, a demonstração usa dados separados.</p><button class="btn outline full" data-action="logout">'+icon('logout')+'Sair da conta</button>'),logout:async()=>{voice?.stop();if(countTimer)cancelCountdown();if(activeAlert)activeAlert.finished=true;await fb?.signOut(auth);stopLocation();closeModal();navigate('inicio')},clearData:()=>modal(modalHead('Apagar dados deste aparelho?')+'<p>Contatos e preferências desta conta serão apagados neste navegador. Isso não apaga SMS ou mensagens de WhatsApp já enviados.</p><div class="flow"><button class="btn outline" data-action="closeModal">Voltar</button><button class="btn danger" data-action="confirmClear">Apagar dados locais</button></div>'),confirmClear:()=>{voice?.stop();if(countTimer)cancelCountdown();localStorage.removeItem(storagePrefix+scope+':contacts');localStorage.removeItem(storagePrefix+scope+':prefs');activeAlert=null;stopLocation();loadScope();closeModal();render();toast('Dados locais apagados.')}};
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action],[data-page],[data-type],[data-edit],[data-delete],[data-manual]');if(!btn)return;if(btn.dataset.action){const r=actions[btn.dataset.action]?.(btn);if(r?.catch)r.catch(()=>toast('Não foi possível concluir esta ação. Tente novamente.'))}else if(btn.dataset.page)navigate(btn.dataset.page);else if(btn.dataset.type){selected=selected===btn.dataset.type?'geral':btn.dataset.type;render()}else if(btn.dataset.manual)manualContact(contacts.find(c=>c.id===btn.dataset.manual));else if(btn.dataset.edit)contactForm(contacts.find(c=>c.id===btn.dataset.edit));else if(btn.dataset.delete){const c=contacts.find(c=>c.id===btn.dataset.delete);modal(modalHead('Remover contato?')+'<p>'+esc(c.name)+' deixará de fazer parte dos próximos pedidos. Mensagens já enviadas não serão apagadas.</p><div class="flow"><button class="btn outline" data-action="closeModal">Voltar</button><button class="btn danger" id="confirmDelete">Remover</button></div>');$('#confirmDelete').onclick=()=>{contacts=contacts.filter(x=>x.id!==c.id);saveContacts();closeModal();render()}}});
document.addEventListener('change',e=>{if(e.target.id==='contactsFile'){importContactsFile(e.target)}else if(e.target.id==='appTheme'){if(['light','dark','system'].includes(e.target.value)){prefs.theme=e.target.value;savePrefs()}}else if(e.target.dataset.contactToggle){const c=contacts.find(c=>c.id===e.target.dataset.contactToggle);c.active=e.target.checked;saveContacts();render()}else if(e.target.dataset.pref){prefs[e.target.dataset.pref]=e.target.checked;savePrefs()}else if(e.target.id==='demoToggle')setDemo(e.target.checked)});
document.addEventListener('submit',e=>{if(e.target.id==='contactForm'){e.preventDefault();const name=$('#contactName').value.trim(),phone=normalizePhone($('#contactPhone').value);if(!name||name.length>50||!phone){$('#contactError').textContent='Preencha o nome e um telefone válido com DDD.';return}if(contacts.some(c=>c.phone===phone&&c.id!==editId)){$('#contactError').textContent='Esse telefone já está na sua rede.';return}const c={id:editId||crypto.randomUUID(),name,relation:$('#contactRelation').value.trim(),phone,consent:$('#contactConsent').checked,active:editId?contacts.find(c=>c.id===editId).active:true};contacts=editId?contacts.map(x=>x.id===editId?c:x):[...contacts,c];saveContacts();closeModal();render();toast('Contato salvo neste aparelho.')}else if(e.target.id==='phoneForm'){e.preventDefault();phoneLogin()}else if(e.target.id==='codeForm'){e.preventDefault();codeLogin()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#reading')){$('#reading').remove();return}if($('#modalRoot').firstChild){closeModal();return}if(countTimer)cancelCountdown()}if(e.key==='Tab'&&$('#modalRoot').firstChild){const nodes=$$('#modalRoot button:not(:disabled),#modalRoot a[href],#modalRoot input,#modalRoot select');if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installedEvent=e});window.addEventListener('offline',()=>{if(voice?.getState().mode==='browser')voice.stop('Sem internet. Escuta online desligada.');$('#offlineBar').hidden=false;toast('Sem internet. Use os recursos locais ou prepare o SOS manual.');updateFeatureUI()});window.addEventListener('online',()=>{$('#offlineBar').hidden=true;updateFeatureUI()});window.addEventListener('blur',()=>stopHold());window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(pages.some(x=>x[0]===p))navigate(p)});window.addEventListener('pagehide',()=>voice?.stop());document.addEventListener('visibilitychange',()=>{if(document.hidden)voice?.stop('Escuta desligada ao sair do aplicativo.');if(document.hidden&&countTimer)cancelCountdown();if(document.hidden&&holdTimer){clearInterval(holdTimer);holdTimer=null;$('#sos')?.classList.remove('holding');if($('#holdText'))$('#holdText').textContent='Segure por 3 segundos'}});
function voicePanel(){const state=voice?.getState();return '<section class="card feature-card"><div class="section-head"><h2>'+icon('volume')+' Comando de voz</h2><span class="pill" data-voice-state role="status">'+esc(state?.message||'Voz indisponível neste navegador.')+'</span></div><p>Diga <strong>“Conecta, preciso de ajuda”</strong> após ativar a escuta. O SOS mantém os cinco segundos para cancelar e respeita o modo de demonstração.</p><p class="small muted">Escuta por até 10 minutos com o app aberto e em primeiro plano. Não funciona com a tela bloqueada. O microfone nunca é ligado automaticamente.</p><div class="flow feature-actions"><button class="btn primary" data-action="voiceDialog">Ativar comando de voz</button><button class="btn outline" data-action="stopListening">Desligar microfone</button></div></section>'}
function offlineText(){return offlineState==='ready'?'Aplicativo preparado para abrir sem internet.':offlineState==='unsupported'?'Este navegador não permite preparar o aplicativo offline.':offlineState==='error'?'Não foi possível preparar o aplicativo offline. Abra com internet e tente novamente.':'Preparando o aplicativo para uso offline. Mantenha esta página aberta com internet até a confirmação.'}
function offlinePanel(){return '<section class="card feature-card"><div class="section-head"><h2>'+icon('shield')+' Disponível sem internet</h2></div><p data-offline-state role="status">'+esc(offlineText())+'</p><p class="small muted">Contatos salvos, tutorial, temas e demonstração ficam neste aparelho. O SOS manual prepara rascunhos de SMS; você confirma o envio com sinal da operadora. WhatsApp e envios automáticos precisam de internet. Nenhum alerta fica na fila para envio posterior.</p><div class="flow feature-actions"><button class="btn soft" data-action="confirmManualAlert">Preparar SOS manual</button></div></section>'}
function updateFeatureUI(){const state=voice?.getState();$$('[data-voice-state]').forEach(el=>el.textContent=state?.message||'Voz indisponível neste navegador.');$$('[data-offline-state]').forEach(el=>el.textContent=offlineText());const bar=$('#voiceBar');if(bar)bar.hidden=!['checking','starting','listening','downloading'].includes(state?.status)}
function voiceDialog(){if(!voice?.supported){toast('Este navegador não oferece comando de voz. Use o botão SOS.');return}modal(modalHead('Ativar comando de voz')+'<p>Frase: <strong>“Conecta, preciso de ajuda”.</strong> '+(prefs.demo?'A demonstração está ativa: ninguém receberá mensagens.':'O comando inicia o mesmo SOS do botão, com cinco segundos para cancelar.')+'</p><div class="notice">O microfone só será solicitado após sua escolha abaixo. A escuta para ao sair do aplicativo, ativar o modo leitura ou iniciar um pedido. Não gravamos nem guardamos áudio ou transcrições.</div><h3 class="feature-subtitle">Neste aparelho</h3><p class="small muted">Pode funcionar offline em navegadores compatíveis, após preparar o pacote de português. O áudio fica no aparelho neste modo.</p><div class="flow"><button class="btn soft" data-action="startVoiceLocal" '+(!voice.localSupported?'disabled':'')+'>Ouvir neste aparelho</button><button class="btn outline" data-action="downloadVoice" '+(!voice.localSupported||!navigator.onLine?'disabled':'')+'>Preparar português offline</button></div><h3 class="feature-subtitle">Serviço do navegador</h3><p class="small muted">Pode enviar áudio ao provedor do navegador para reconhecimento e depender de internet. Escolha esta opção somente se concordar com esse processamento.</p><button class="btn primary full" data-action="startVoiceBrowser" '+(!navigator.onLine?'disabled':'')+'>Concordo e quero ouvir pelo navegador</button><p class="small muted feature-subtitle" data-voice-state role="status">'+esc(voice.getState().message)+'</p>')}
async function startVoice(mode){if(!voice)return;window.speechSynthesis?.cancel();await voice.start(mode);updateFeatureUI();if(['starting','listening'].includes(voice.getState().status))closeModal()}
function confirmManualAlert(){modal(modalHead('Preparar SOS manual?')+'<p>Ao fim de cinco segundos, o app prepara o pedido para seus contatos ativos. Nenhuma mensagem é enviada automaticamente, mesmo se a internet voltar.</p><div class="notice">Você confirma cada SMS no aplicativo de mensagens, com sinal da operadora. WhatsApp exige internet. Esta é uma ação manual real, inclusive quando a demonstração está ativa.</div><div class="flow feature-actions"><button class="btn outline" data-action="closeModal">Voltar</button><button class="btn danger" data-action="startManualAlert">Iniciar contagem manual</button></div>')}
function manualAlertPage(a){const text=message();const rows=a.contacts.map(c=>'<div class="delivery"><div><b>'+esc(c.name)+'</b><p class="small muted"><span data-opened="'+c.id+'">'+((a.opened[c.id+':sms']||a.opened[c.id+':wa'])?'Rascunho aberto':'Aguardando você')+'</span></p></div><div class="flow"><a class="btn primary" data-action="markOpened" data-mark="'+c.id+':sms" href="'+esc(smsHref(c.phone,text))+'">Preparar SMS</a>'+(navigator.onLine?'<a class="btn outline" data-action="markOpened" data-mark="'+c.id+':wa" href="'+esc(waHref(c.phone,text))+'" target="_blank" rel="noopener noreferrer">Preparar WhatsApp</a>':'<span class="small muted">WhatsApp precisa de internet.</span>')+'</div></div>').join('');return '<div class="page-title"><div><h1>Seu SOS está preparado.</h1><p>Nenhuma mensagem enviada ainda. Toque em um botão por contato e confirme o envio.</p></div></div><section class="card"><div class="notice warning">'+(!navigator.onLine?'Você está sem internet. ':'')+'O app abre o SMS ou o WhatsApp com a mensagem pronta; quem confirma o envio é você. O SMS usa o sinal da operadora e pode ser cobrado. Não há envio posterior automático.</div><p class="manual-message">'+esc(text)+'</p>'+(a.location?'<p class="small muted">Posição registrada às '+new Date(a.location.time).toLocaleTimeString('pt-BR')+'.</p>':'<p class="small muted">Sem localização recente. <button class="textlink" data-action="refreshManualLocation">Tentar obter a localização</button></p>')+(a.contacts.length?rows:'<p class="small muted feature-subtitle">Não há contatos ativos neste pedido. Cadastre suas pessoas de confiança antes de precisar.</p>')+'<div class="flow feature-actions">'+(typeof navigator.share==='function'?'<button class="btn soft" data-action="shareMessage">Compartilhar mensagem</button>':'')+'<button class="btn soft" data-action="copyMessage">Copiar mensagem</button></div><div class="flow feature-actions"><a class="btn outline" href="tel:190">'+icon('phone')+'Ligar 190</a><a class="btn outline" href="tel:180">'+icon('phone')+'Ligar 180</a><button class="btn soft" data-action="finishAlert">Encerrar visualização</button></div><p class="small muted feature-subtitle">190: polícia. 180: Central de Atendimento à Mulher. Ligações dependem da rede telefônica e são iniciadas por você. Abrir um rascunho não comprova envio ou entrega.</p></section>'}
function initOffline(){if(!('serviceWorker' in navigator)){offlineState='unsupported';updateFeatureUI();return}const check=reg=>{const active=reg.active||navigator.serviceWorker.controller;active?.postMessage({type:'CHECK_OFFLINE'})};navigator.serviceWorker.addEventListener('message',event=>{if(event.data?.type==='OFFLINE_STATUS'){offlineState=event.data.ready?'ready':'error';updateFeatureUI()}});navigator.serviceWorker.addEventListener('controllerchange',()=>check({active:navigator.serviceWorker.controller}));navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'}).then(()=>navigator.serviceWorker.ready).then(check).catch(()=>{offlineState='error';updateFeatureUI()})}

let offlineState='pending';
const voice=window.ConectaVoice?.create({onCommand:()=>{closeModal();startCountdown()},onState:()=>updateFeatureUI()})||null;
$('#brand').innerHTML=logo;$('#sideShield').innerHTML=icon('shield');$('#quickExit').innerHTML=icon('book');$('#sideInstall').innerHTML=icon('download')+'Instalar aplicativo';$('#offlineBar').hidden=navigator.onLine;loadScope();page=pages.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'inicio';render();
(runtime.static&&!runtime.apiBase?Promise.resolve(runtime.config):fetch((runtime.apiBase||'')+'/api/config',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Configuração indisponível');return r.json()})).then(async c=>{config=c;if(!c.live){prefs.demo=true;savePrefs()}render();if(c.firebase)try{await initFirebase()}catch{toast('Não foi possível iniciar o login. A demonstração continua disponível.')}}).catch(()=>toast('Configuração online indisponível. Apenas demonstração.'));
initOffline();window.matchMedia?.('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(prefs.theme==='system')applyPrefs()});
